                    <div style={{ display: 'flex', justifyContent: 'flex-end', gap: '12px', marginTop: '20px' }}>
                      <button onClick={submitAssignment} style={{ padding: '12px 28px', background: '#48bb78', color: 'white', border: 'none', borderRadius: '8px', cursor: 'pointer' }}>Submit</button>
                      <button onClick={() => { setSelectedAssignment(null); setSubmissionText(''); }} style={{ padding: '12px 28px', background: '#e53e3e', color: 'white', border: 'none', borderRadius: '8px', cursor: 'pointer' }}>Cancel</button>
                    </div>
                  </div>
                </div>
              )}

              {showFileModal && (
                <div style={{ position: 'fixed', inset: 0, background: 'rgba(0,0,0,0.7)', display: 'flex', alignItems: 'center', justifyContent: 'center', zIndex: 1000 }}>
                  <div style={{ background: 'white', borderRadius: '16px', padding: '30px', width: '90%', maxWidth: '700px', maxHeight: '90vh', overflow: 'auto', boxShadow: '0 20px 50px rgba(0,0,0,0.3)' }}>
                    <h3 style={{ marginTop: 0, color: '#2d3748' }}>{user.role === 'instructor' ? 'Student Submission' : 'Your Submission'}</h3>
                    <div style={{ background: '#f8fafc', padding: '20px', borderRadius: '12px', whiteSpace: 'pre-wrap' }}>{currentSubmissionText || 'No content'}</div>
                    <button onClick={() => setShowFileModal(false)} style={{ marginTop: '20px', padding: '12px 28px', background: '#718096', color: 'white', border: 'none', borderRadius: '8px', cursor: 'pointer' }}>Close</button>
                  </div>
                </div>
              )}

              {showGradeModal && submissionToGrade && (
                <div style={{ position: 'fixed', inset: 0, background: 'rgba(0,0,0,0.7)', display: 'flex', alignItems: 'center', justifyContent: 'center', zIndex: 1000 }}>
                  <div style={{ background: 'white', borderRadius: '16px', padding: '30px', width: '90%', maxWidth: '700px', boxShadow: '0 20px 50px rgba(0,0,0,0.3)' }}>
                    <h3 style={{ marginTop: 0, color: '#2d3748' }}>Grade Submission</h3>
                    <p><strong>Student:</strong> {getStudentName(submissionToGrade.studentid)}</p>
                    <p><strong>Assignment:</strong> {getAssignmentTitle(submissionToGrade.assignmentid)}</p>
                    <div style={{ background: '#f8fafc', padding: '20px', borderRadius: '12px', margin: '15px 0' }}>
                      <strong>Answer:</strong>
                      <div style={{ marginTop: '10px', whiteSpace: 'pre-wrap' }}>{submissionToGrade.fileurl || 'No submission'}</div>
                    </div>
                    <input type="number" min="0" max="100" value={gradeValue} onChange={(e) => setGradeValue(e.target.value)} placeholder="Grade" style={{ width: '100%', padding: '12px', borderRadius: '8px', border: '2px solid #e2e8f0', margin: '10px 0' }} />
                    <textarea value={feedbackText} onChange={(e) => setFeedbackText(e.target.value)} placeholder="Feedback" rows="4" style={{ width: '100%', padding: '12px', borderRadius: '8px', border: '2px solid #e2e8f0' }} />
                    <div style={{ display: 'flex', justifyContent: 'flex-end', gap: '12px', marginTop: '20px' }}>
                      <button onClick={gradeSubmission} style={{ padding: '12px 28px', background: '#48bb78', color: 'white', border: 'none', borderRadius: '8px', cursor: 'pointer' }}>Save</button>
                      <button onClick={() => { setShowGradeModal(false); setSubmissionToGrade(null); }} style={{ padding: '12px 28px', background: '#e53e3e', color: 'white', border: 'none', borderRadius: '8px', cursor: 'pointer' }}>Cancel</button>
                    </div>
                  </div>
                </div>
              )}

              {showConfirmDelete && (
                <div style={{ position: 'fixed', inset: 0, background: 'rgba(0,0,0,0.7)', display: 'flex', alignItems: 'center', justifyContent: 'center', zIndex: 1000 }}>
                  <div style={{ background: 'white', borderRadius: '16px', padding: '30px', textAlign: 'center', boxShadow: '0 20px 50px rgba(0,0,0,0.3)' }}>
                    <h3 style={{ margin: '0 0 20px', color: '#2d3748' }}>Confirm Delete</h3>
                    <p style={{ margin: '0 0 30px', color: '#718096' }}>Are you sure you want to delete this permanently?</p>
                    <div style={{ display: 'flex', justifyContent: 'center', gap: '15px' }}>
                      <button onClick={handleDelete} style={{ padding: '12px 28px', background: '#e53e3e', color: 'white', border: 'none', borderRadius: '8px', cursor: 'pointer' }}>Yes, Delete</button>
                      <button onClick={() => { setShowConfirmDelete(false); setItemToDelete(null); setDeleteBase(''); }} style={{ padding: '12px 28px', background: '#718096', color: 'white', border: 'none', borderRadius: '8px', cursor: 'pointer' }}>Cancel</button>
                    </div>
                  </div>
                </div>
              )}

              {showChat && (
                <div style={{ position: 'fixed', bottom: '100px', right: '30px', width: '380px', height: '500px', background: 'white', borderRadius: '16px', boxShadow: '0 20px 50px rgba(0,0,0,0.3)', display: 'flex', flexDirection: 'column', zIndex: 1000 }}>
                  <div style={{ padding: '16px', background: '#667eea', color: 'white', borderRadius: '16px 16px 0 0', fontWeight: '600', fontSize: '1.1rem', display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
                    NM Portal Assistant
                    <button onClick={() => setShowChat(false)} style={{ background: 'none', border: 'none', color: 'white', fontSize: '24px', cursor: 'pointer' }}>×</button>
                  </div>
                  <div style={{ flex: 1, padding: '16px', overflowY: 'auto', background: '#f8fafc' }}>
                    {chatMessages.map((msg, i) => (
                      <div key={i} style={{ margin: '10px 0', textAlign: msg.sender === 'user' ? 'right' : 'left' }}>
                        <div style={{ display: 'inline-block', maxWidth: '80%', padding: '12px 16px', borderRadius: '16px', background: msg.sender === 'user' ? '#667eea' : '#e2e8f0', color: msg.sender === 'user' ? 'white' : '#333' }}>
                          {msg.text}
                        </div>
                      </div>
                    ))}
                    {chatLoading && <div style={{ textAlign: 'left' }}><div style={{ display: 'inline-block', padding: '12px 16px', background: '#e2e8f0', borderRadius: '16px' }}>Thinking...</div></div>}
                    <div ref={chatEndRef} />
                  </div>
                  <div style={{ padding: '16px', borderTop: '1px solid #e2e8f0', display: 'flex' }}>
                    <input type="text" value={chatInput} onChange={(e) => setChatInput(e.target.value)} onKeyPress={(e) => e.key === 'Enter' && sendChatMessage()} placeholder="Ask about the portal..." style={{ flex: 1, padding: '12px', borderRadius: '8px', border: '2px solid #e2e8f0', fontSize: '1rem' }} />
                    <button onClick={sendChatMessage} disabled={chatLoading} style={{ marginLeft: '10px', padding: '12px 20px', background: '#667eea', color: 'white', border: 'none', borderRadius: '8px', cursor: 'pointer' }}>Send</button>
                  </div>
                </div>
              )}
              <button onClick={() => setShowChat(true)} style={{ position: 'fixed', bottom: '30px', right: '30px', width: '60px', height: '60px', background: '#667eea', color: 'white', border: 'none', borderRadius: '50%', fontSize: '28px', cursor: 'pointer', boxShadow: '0 8px 25px rgba(0,0,0,0.3)', zIndex: 1000, display: 'flex', alignItems: 'center', justifyContent: 'center' }}>AI</button>
            </div>
          </main>

          <footer style={{ textAlign: 'center', padding: '30px', color: 'white', background: 'rgba(0,0,0,0.3)', marginTop: '50px' }}>
            <h3 style={{ margin: '0 0 10px' }}>Student Portal © 2025</h3>
            <p style={{ margin: 0, opacity: 0.9 }}>Nikko Manuel - Marlon Chipa Learning Management System</p>
          </footer>
        </>
      )}
    </div>
  );
}

export default App;
